<?php require dirname(__DIR__).'/app/bootstrap.php'; require dirname(__DIR__).'/app/layout.php';
$products=db()->query('SELECT * FROM products ORDER BY created_at DESC, productId DESC LIMIT 3')->fetchAll();$photosByProduct=photosForProducts($products);pageStart('Home'); ?>
<section class="hero"><h1>Welcome to Simple Shop</h1><p>Discover our latest products.</p><a class="button" href="/products.php">Browse all products</a></section><h2>Latest products</h2>
<div class="grid"><?php foreach($products as $p): ?><article class="card"><?php $gallery=galleryForProduct($p,$photosByProduct);$first=$gallery[0]['url']??photoUrl($p['photo_key']);if($first): ?><img src="<?= e($first) ?>" alt="<?= e($p['name']) ?>"><?php endif; ?><h3><?= e($p['name']) ?></h3><p><?= e($p['description']) ?></p><strong>$<?= number_format((float)$p['price'],2) ?></strong></article><?php endforeach; ?></div><?php pageEnd();
